/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: renderHome, sessionFor, json
 * Tests
 *   - centers the retry action when Home cannot load
 *   - a failed initial session shows an error and retries the session before account-bound Home
 *   - retrying a failed session with retained old data never refetches the old viewer Home in parallel
 *   - a Home-only failure retries Home without resetting the successful session
 *   - renders the same Carousel attached twice as two independent sections
 *   - records a mood card as an explicit suggested search
 * @end-catalog */

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter } from 'react-router';

import { browserSessionQueryKey } from '../../api/session';
import type { BrowserSession } from '../../api/schemas';
import { SearchQueryProvider } from '../search/SearchQueryProvider';
import { readSearchHistory } from '../search/searchHistory';
import { HomePage } from './HomePage';

/** Renders Home with deterministic query behavior for its fallback states. */
const renderHome = (options: { bootstrap?: boolean; session?: BrowserSession } = {}) => {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  if (!options.bootstrap) queryClient.setQueryData(browserSessionQueryKey, options.session ?? null);
  const view = render(
    <QueryClientProvider client={queryClient}>
      <MemoryRouter>
        <SearchQueryProvider><HomePage /></SearchQueryProvider>
      </MemoryRouter>
    </QueryClientProvider>
  );
  return { ...view, queryClient };
};

/** A synthetic authoritative session; Home must wait for its result before choosing a viewer. */
const sessionFor = (id: string): BrowserSession => ({ user: {
  id, email: `${id}@example.test`, role: 'user', displayName: id, avatarRevision: 0, avatar: null, emailVerified: true
} });
const json = (body: unknown, status = 200, viewer?: string) => new Response(JSON.stringify(body), {
  status, headers: { 'Content-Type': 'application/json', ...(viewer ? { 'X-Finitude-Account-Viewer': viewer } : {}) }
});

afterEach(() => {
  vi.restoreAllMocks();
  window.localStorage.clear();
});

test('centers the retry action when Home cannot load', async () => {
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response(null, { status: 503 })));
  renderHome();

  const retryButton = await screen.findByRole('button', { name: 'Try again' });

  expect(getComputedStyle(retryButton.parentElement!).justifyContent).toBe('center');
});

test('a failed initial session shows an error and retries the session before account-bound Home', async () => {
  const user = userEvent.setup(), reads: string[] = [], viewer = 'lorem-viewer';
  let releaseSession!: () => void;
  const sessionGate = new Promise<void>(resolve => { releaseSession = resolve; });
  let sessionReads = 0;
  vi.stubGlobal('fetch', vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const path = String(input);
    if (path === '/auth/browser/session' || path === '/api/listener/v1/home') reads.push(path);
    if (path === '/auth/browser/session') {
      if (++sessionReads === 1) return json({ message: 'Unavailable' }, 503);
      await sessionGate;
      return json(sessionFor(viewer));
    }
    if (path === '/api/listener/v1/home') {
      expect(new Headers(init?.headers).get('X-Finitude-Account-Viewer')).toBe(viewer);
      return json({ title: 'Recovered Home', sections: [] }, 200, viewer);
    }
    return json({});
  }));
  renderHome({ bootstrap: true });

  expect(await screen.findByRole('heading', { name: 'Home is taking a quiet moment' })).toBeInTheDocument();
  expect(screen.queryByRole('region', { name: 'Loading Home' })).not.toBeInTheDocument();
  await user.click(screen.getByRole('button', { name: 'Try again' }));
  await vi.waitFor(() => expect(sessionReads).toBe(2));
  expect(reads).toEqual(['/auth/browser/session', '/auth/browser/session']);
  await act(async () => { releaseSession(); });

  expect(await screen.findByRole('heading', { name: 'Recovered Home' })).toBeInTheDocument();
  expect(reads).toEqual(['/auth/browser/session', '/auth/browser/session', '/api/listener/v1/home']);
});

test('retrying a failed session with retained old data never refetches the old viewer Home in parallel', async () => {
  const user = userEvent.setup(), oldViewer = 'old-viewer', nextViewer = 'next-viewer', homeViewers: Array<string | null> = [];
  let releaseSession!: () => void;
  const sessionGate = new Promise<void>(resolve => { releaseSession = resolve; });
  let sessionReads = 0;
  vi.stubGlobal('fetch', vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    if (String(input) === '/auth/browser/session') {
      if (++sessionReads === 1) return json({ message: 'Unavailable' }, 503);
      await sessionGate;
      return json(sessionFor(nextViewer));
    }
    if (String(input) === '/api/listener/v1/home') {
      const viewer = new Headers(init?.headers).get('X-Finitude-Account-Viewer'); homeViewers.push(viewer);
      return viewer === oldViewer ? json({ message: 'Unavailable' }, 503)
        : json({ title: 'Current Viewer Home', sections: [] }, 200, nextViewer);
    }
    return json({});
  }));
  const { queryClient } = renderHome({ session: sessionFor(oldViewer) });
  expect(await screen.findByRole('button', { name: 'Try again' })).toBeInTheDocument();
  await act(async () => { await queryClient.refetchQueries({ queryKey: browserSessionQueryKey, exact: true }); });
  expect(homeViewers).toEqual([oldViewer]);
  await user.click(screen.getByRole('button', { name: 'Try again' }));
  await vi.waitFor(() => expect(sessionReads).toBe(2));
  expect(homeViewers).toEqual([oldViewer]);
  await act(async () => { releaseSession(); });

  expect(await screen.findByRole('heading', { name: 'Current Viewer Home' })).toBeInTheDocument();
  expect(homeViewers).toEqual([oldViewer, nextViewer]);
});

test('a Home-only failure retries Home without resetting the successful session', async () => {
  const user = userEvent.setup(), viewer = 'lorem-viewer';
  let homeReads = 0, sessionReads = 0;
  vi.stubGlobal('fetch', vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    if (String(input) === '/auth/browser/session') { sessionReads += 1; return json(sessionFor(viewer)); }
    if (String(input) === '/api/listener/v1/home') {
      expect(new Headers(init?.headers).get('X-Finitude-Account-Viewer')).toBe(viewer);
      return ++homeReads === 1 ? json({ message: 'Unavailable' }, 503)
        : json({ title: 'Recovered Home', sections: [] }, 200, viewer);
    }
    return json({});
  }));
  renderHome({ session: sessionFor(viewer) });
  await user.click(await screen.findByRole('button', { name: 'Try again' }));

  expect(await screen.findByRole('heading', { name: 'Recovered Home' })).toBeInTheDocument();
  expect([homeReads, sessionReads]).toEqual([2, 0]);
});

test('renders the same Carousel attached twice as two independent sections', async () => {
  const consoleError = vi.spyOn(console, 'error');
  const album = {
    contentType: 'album',
    id: '0123456789abcdef01234567',
    title: 'Lorem Ipsum',
    artworkUrl: '',
    artistNames: ['Dolor Ensemble'],
    releaseDate: null
  };
  const attachment = { title: 'Sit Amet Picks', presentation: 'carousel', items: [album, album] };
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response(JSON.stringify({
    title: 'Evening selection',
    // Each attachment of one Carousel carries its own persisted Page item ID.
    sections: [
      { id: '1123456789abcdef01234567', ...attachment },
      { id: '2123456789abcdef01234567', ...attachment }
    ]
  }), { status: 200, headers: { 'Content-Type': 'application/json' } })));
  const { container } = renderHome();

  const headings = await screen.findAllByRole('heading', { name: 'Sit Amet Picks' });

  expect(headings.map((heading) => heading.id)).toEqual([
    'listener-section-1123456789abcdef01234567',
    'listener-section-2123456789abcdef01234567'
  ]);
  const carousels = container.querySelectorAll('[data-presentation="carousel"]');
  expect(Array.from(carousels, (carousel) => carousel.children.length)).toEqual([2, 2]);
  expect(consoleError.mock.calls.flat().join(' ')).not.toMatch(/same key/);
});

test('records a mood card as an explicit suggested search', async () => {
  const user = userEvent.setup();
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response(JSON.stringify({
    title: 'Evening selection',
    sections: []
  }), { status: 200, headers: { 'Content-Type': 'application/json' } })));
  renderHome();

  expect(await screen.findByRole('heading', { name: 'Evening selection' })).toBeInTheDocument();
  expect(screen.queryByText('Leave room for the music.')).not.toBeInTheDocument();
  await user.click(await screen.findByRole('link', { name: /Quiet focus/ }));

  expect(readSearchHistory(null)).toEqual(['ambient']);
});
